  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 5, $j$2.1 The Romantic Imagination$j$, $j${"readings": [{"title": "Psalm 139 (King James Version)", "url": "/portal/bible/Psalms/139"}], "body": "In the early 1800s, American writers turned toward imagination, emotion, nature and the individual. This movement is called Romanticism. Washington Irving wrote humorous tales set in the Hudson Valley. James Fenimore Cooper wrote adventures of the frontier. Edgar Allan Poe wrote poems and stories of mystery and dread. Nathaniel Hawthorne explored sin, guilt and conscience in Puritan New England.\n\nKey ideas of Romanticism:\n1. Feeling and imagination matter as much as reason.\n2. Nature is beautiful, powerful and full of meaning.\n3. The individual is valuable.\n4. Mystery and the unknown fascinate readers.\n\nTo judge how a key element adds depth to a story, ask how it works. Setting is the time and place. Mood is the feeling the reader gets. Symbol is an object that stands for a bigger idea. Imagery is language that appeals to the senses.\n\nRead this original passage:\n\nThe old house stood at the edge of the marsh, and the fog lay against its windows like a pale hand. Inside, a single candle burned in the hall. Mara counted her heartbeats and listened to the clock, which had stopped years ago and yet seemed to tick.\n\nSetting: an old house at the edge of a marsh. Mood: uneasy and mysterious. Imagery: the fog like a pale hand; the candle; the stopped clock that seems to tick. Symbol: the stopped clock may stand for the past that will not let go.\n\nYour task: (1) Name the setting and the mood. (2) Quote two images that build the mood. (3) Explain what the stopped clock might symbolize and how it adds depth.\n\nFlorida standards: ELA.11.R.1.1, ELA.11.R.1.4.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.11.R.1.1, ELA.11.R.1.4", "script": "Welcome back. Today we step into the age of imagination. In the early eighteen hundreds, American writers turned toward feeling, nature and the value of the individual. We call this movement Romanticism.\n\nListen to some of the voices. Washington Irving wrote humorous tales set in the Hudson Valley. James Fenimore Cooper wrote adventures on the frontier. Edgar Allan Poe wrote poems and stories of mystery and dread. And Nathaniel Hawthorne explored sin, guilt and conscience in Puritan New England.\n\nNow watch this. The Romantics believed four things. Feeling and imagination matter as much as reason. Nature is beautiful, powerful and full of meaning. The individual is valuable. And mystery fascinates readers.\n\nWhen we read a story, we ask how its key elements add depth. Setting is the time and place. Mood is the feeling the reader gets. A symbol is an object that stands for a bigger idea. And imagery is language that appeals to the senses.\n\nLet us read an original passage. The old house stood at the edge of the marsh, and the fog lay against its windows like a pale hand. Inside, a single candle burned in the hall. Mara counted her heartbeats and listened to the clock, which had stopped years ago and yet seemed to tick.\n\nThe setting is an old house at the edge of a marsh. The mood is uneasy and mysterious. The imagery includes the fog like a pale hand, the single candle, and the clock that stopped but seems to tick. And the symbol? The stopped clock may stand for a past that will not let go.\n\nYour task today. Name the setting and the mood. Quote two images that build the mood. And explain what the stopped clock might symbolize and how it adds depth. Take the four question check when you finish.\n\nA writer who sees deeply helps a reader see deeply. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.1 The Romantic Imagination$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 6, $j$2.2 Hawthorne, Allegory and the Parable$j$, $j${"readings": [{"title": "Matthew 13 (King James Version)", "url": "/portal/bible/Matthew/13"}], "body": "An allegory is a story in which characters, objects and events stand for ideas about life, faith or society. The reader looks at two levels: the surface story and the deeper meaning. Nathaniel Hawthorne used allegory often. His stories use symbols such as a veil, a letter, or a birthmark to explore secret sin and the need for honesty.\n\nA parable is a short story that teaches a spiritual lesson. In Matthew 13:3, Jesus spoke many things unto them in parables, saying, Behold, a sower went forth to sow. Parables use ordinary scenes (seeds, lamps, coins) to point to heavenly truth.\n\nA universal theme is a message that appears across times and cultures. Examples: pride leads to a fall; honesty heals; love is stronger than fear; hidden sin harms the soul.\n\nRead this original allegory:\n\nA traveler carried a lantern with a cracked glass. All night he complained that the wind made the light flicker. A child walked beside him and said, Sir, the wind does not break the light. The crack does. The traveler mended the glass and walked on, and the road grew clear.\n\nSurface story: a traveler with a cracked lantern. Deeper meaning: we often blame outside troubles for problems that come from our own flaws. The lantern stands for a person's heart, the crack for a hidden fault, the wind for outside pressure. Universal theme: honest self examination leads to growth.\n\nYour task: (1) Tell the surface story in one sentence. (2) Explain what the lantern, the crack and the wind stand for. (3) State the universal theme and connect it to another story or Scripture you know.\n\nFlorida standards: ELA.11.R.3.1, ELA.11.R.1.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.11.R.3.1, ELA.11.R.1.2", "script": "Now we meet a powerful tool, the allegory. An allegory is a story in which characters, objects and events stand for ideas about life, faith or society. When we read an allegory, we look at two levels. The surface story, and the deeper meaning.\n\nNathaniel Hawthorne used allegory often. His stories use symbols like a veil, a letter or a birthmark to explore secret sin and the need for honesty.\n\nListen, this is not far from Scripture. A parable is a short story that teaches a spiritual lesson. In Matthew chapter thirteen, verse three, the Bible says, And he spake many things unto them in parables, saying, Behold, a sower went forth to sow. Jesus used ordinary things like seeds, lamps and coins to point to heavenly truth.\n\nAnother key idea is the universal theme. That is a message that appears across times and cultures. Pride leads to a fall. Honesty heals. Love is stronger than fear. Hidden sin harms the soul.\n\nNow watch this. Let us read an original allegory. A traveler carried a lantern with a cracked glass. All night he complained that the wind made the light flicker. A child walked beside him and said, Sir, the wind does not break the light. The crack does. The traveler mended the glass and walked on, and the road grew clear.\n\nThe surface story is a traveler with a cracked lantern. The deeper meaning is that we often blame outside troubles for problems that come from our own flaws. The lantern stands for the heart. The crack stands for a hidden fault. The wind stands for outside pressure. And the universal theme is that honest self examination leads to growth.\n\nYour task today. Tell the surface story in one sentence. Explain what the lantern, the crack and the wind stand for. And state the universal theme and connect it to a story or Scripture you know. Take the four question check when you finish.\n\nTruth loves the light. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.2 Hawthorne, Allegory and the Parable$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 7, $j$2.3 Emerson, Thoreau and Transcendentalism$j$, $j${"readings": [{"title": "Matthew 6 (King James Version)", "url": "/portal/bible/Matthew/6"}], "body": "Transcendentalism was a movement of the 1830s and 1840s in New England. Ralph Waldo Emerson wrote essays such as Nature and Self Reliance. Henry David Thoreau lived for two years beside Walden Pond and wrote Walden. They taught that nature reveals truth, that each person should think independently, and that simple living frees the mind.\n\nKey ideas:\n1. Self reliance: trust your own conscience and thoughts.\n2. Nature: a source of beauty and spiritual insight.\n3. Simplicity: owning less so you can live more.\n4. Nonconformity: resisting pressure to follow the crowd when it is wrong.\n\nAn essay has a thesis (the main claim), supporting paragraphs and a conclusion. To find the main idea of an essay, look at the thesis and the topic sentences. To see how the author accomplishes the goal, look at examples, images and tone.\n\nRead this original excerpt in the Transcendentalist spirit:\n\nA man who borrows every opinion lives in a rented house. Let him build one of his own, if only a small cabin of honest thoughts. The pond is not richer for being crowded, nor is the soul.\n\nThesis: independent thinking is better than borrowed opinions. Images: a rented house, a small cabin, a pond. Tone: calm and confident.\n\nA caution from Scripture: independence must be guided by truth. Proverbs 3:5 says, Trust in the LORD with all thine heart; and lean not unto thine own understanding. Self reliance is healthy when it is anchored in God's wisdom.\n\nYour task: (1) State the thesis in your own words. (2) Explain two images. (3) Describe how Scripture adds balance to the idea of self reliance.\n\nFlorida standards: ELA.11.R.1.2, ELA.11.R.2.2, ELA.11.R.2.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.11.R.1.2, ELA.11.R.2.2, ELA.11.R.2.3", "script": "Now we step into New England in the eighteen thirties and forties, where a movement called Transcendentalism took root. Ralph Waldo Emerson wrote essays like Nature and Self Reliance. Henry David Thoreau lived for two years beside Walden Pond and wrote about it in Walden.\n\nListen to what they taught. First, self reliance. Trust your own conscience and your own thinking. Second, nature. Nature is a source of beauty and spiritual insight. Third, simplicity. Own less so you can live more. And fourth, nonconformity. Do not follow the crowd when the crowd is wrong.\n\nNow watch this. An essay has a thesis, which is the main claim. It has supporting paragraphs, and it has a conclusion. To find the main idea, look at the thesis and the topic sentences. Then to see how the author reaches the goal, look at the examples, the images and the tone.\n\nLet us read an original excerpt in this spirit. A man who borrows every opinion lives in a rented house. Let him build one of his own, if only a small cabin of honest thoughts. The pond is not richer for being crowded, nor is the soul.\n\nThe thesis is that independent thinking is better than borrowed opinions. The images are a rented house, a small cabin and a pond. And the tone is calm and confident.\n\nNow a caution, and this is important. Independence must be guided by truth. Proverbs chapter three, verse five says, Trust in the LORD with all thine heart; and lean not unto thine own understanding. Self reliance is healthy when it is anchored in the wisdom of God.\n\nYour task today. State the thesis in your own words. Explain two images. And describe how Scripture adds balance to the idea of self reliance. Take the four question check when you finish.\n\nThink for yourself, and let God shape what you think. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.3 Emerson, Thoreau and Transcendentalism$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 8, $j$2.4 Whitman, Dickinson and the Poetry of the Age$j$, $j${"readings": [{"title": "Psalm 8 (King James Version)", "url": "/portal/bible/Psalms/8"}], "body": "Two poets changed American verse in the 1800s. Walt Whitman wrote long, free flowing lines about democracy, the body, workers and the American people. His poems use free verse, which does not follow a regular rhyme or meter. Emily Dickinson wrote short, compressed poems about nature, death, faith and the mind. She often used dashes and slant rhyme, in which the ending sounds are similar but not exact.\n\nFigurative language gives words more than their plain meaning. Types include: metaphor (one thing is another), simile (like or as), personification (giving human traits to non human things), and hyperbole (exaggeration).\n\nTo restate a poem in your own words, find the literal meaning first, then explain the figurative layer.\n\nRead this original poem:\n\nThe morning is a patient hand\nthat opens every door.\nIt lifts the shade from sleeping land\nand asks for nothing more.\n\nLiteral: morning arrives and light fills the land. Figurative: the morning is a patient hand (metaphor and personification). Restatement in your own words: Each day comes gently and gives us light and a fresh chance without asking anything in return.\n\nCompare with Scripture: Lamentations 3:23 says of the LORD's mercies, They are new every morning: great is thy faithfulness.\n\nYour task: (1) Name the figurative language in the poem and quote it. (2) Restate the poem in your own words. (3) Write two lines of your own with a simile or metaphor about a time of day.\n\nFlorida standards: ELA.11.R.1.4, ELA.11.R.3.1, ELA.11.R.3.2.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.11.R.1.4, ELA.11.R.3.1, ELA.11.R.3.2", "script": "Now we turn to poetry. Two poets changed American verse in the eighteen hundreds, Walt Whitman and Emily Dickinson.\n\nWalt Whitman wrote long, flowing lines about democracy, workers, the body and the American people. His poems use free verse, which means no regular rhyme or meter. Emily Dickinson did the opposite in length. She wrote short, compressed poems about nature, faith, death and the mind. She often used slant rhyme, where the ending sounds are close but not exact.\n\nListen, poetry runs on figurative language. That means words with more than their plain meaning. A metaphor says one thing is another. A simile uses like or as. Personification gives human traits to things that are not human. And hyperbole is exaggeration.\n\nNow watch this. To restate a poem in your own words, first find the literal meaning. What is actually happening? Then explain the figurative layer. What does the picture mean?\n\nLet us read an original poem. The morning is a patient hand that opens every door. It lifts the shade from sleeping land and asks for nothing more.\n\nThe literal meaning is that morning comes and light fills the land. The figurative language is the patient hand, which is a metaphor and personification. And here is a restatement in plain words. Each day comes gently and gives us light and a fresh chance without asking anything in return.\n\nCompare that to Scripture. Lamentations chapter three, verse twenty three says of the LORD's mercies, They are new every morning: great is thy faithfulness.\n\nYour task today. Name the figurative language and quote it. Restate the poem in your own words. And write two lines of your own with a simile or metaphor about a time of day. Take the four question check when you finish.\n\nA good poem opens a window, and good faith opens the sky. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.4 Whitman, Dickinson and the Poetry of the Age$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 2, $j$Assessment 2: Analyzing a Symbolic Passage$j$, $j${"prompt": "Read this original passage and write an analysis of at least 150 words.\n\nAt the edge of the village stood a bridge with one broken plank. Every traveler stepped over it without a word, and every traveler told himself that someone else would fix it. One autumn a young girl came with a hammer and a board. Behind her the whole village stood watching, ashamed. By evening the bridge was whole, and no one spoke of who had been first.\n\nIn your analysis: (1) Tell the surface story in two sentences. (2) Explain what the broken plank, the bridge and the girl might symbolize. (3) State a universal theme and connect it to one idea in Scripture, such as James 4:17 (Therefore to him that knoweth to do good, and doeth it not, to him it is sin). (4) Tell how the author uses setting, imagery or contrast to add depth. (5) Use complete sentences and give quotations from the passage as evidence.", "rubric": "100 points. Surface story: 15 points. Symbols explained: 25 points. Universal theme with Scripture connection: 25 points. Author's craft with quoted evidence: 25 points. Grammar and complete sentences: 10 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 2: Analyzing a Symbolic Passage$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 2, $j$Discussion 2: Thinking for Yourself, Guided by Truth$j$, $j${"prompt": "The Transcendentalists urged people to think for themselves, while Scripture tells us to trust in the LORD. Write a post of at least 120 words that (1) explains what independent thinking means to you, (2) describes a time when you stood for what was right even when others did not, (3) tells how faith and wisdom help guide your own thinking, and (4) connects your answer to Proverbs 3:5, which says, Trust in the LORD with all thine heart; and lean not unto thine own understanding. Then write a respectful reply of at least 40 words to another student, or answer this question: When is it right to disagree with the crowd, and how can we do it kindly? Keep your language clean and your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 2: Thinking for Yourself, Guided by Truth$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 6, $j$Check 2.1: The Romantic Imagination$j$, $j${"questions": [{"q": "Romanticism values:", "options": ["Only machines", "Only facts and numbers", "Only rules and laws", "Imagination, emotion, nature and the individual"]}, {"q": "A symbol is:", "options": ["A date", "A list of facts", "An object that stands for a bigger idea", "A kind of punctuation"]}, {"q": "The feeling a reader gets from a passage is the:", "options": ["Rhyme", "Mood", "Plot", "Title"]}, {"q": "Which writer is known for mystery and dread in poems and stories?", "options": ["Edgar Allan Poe", "Patrick Henry", "Benjamin Franklin", "Thomas Paine"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: The Romantic Imagination$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,1,0}'::int[], array[$j$Romantic writers emphasized feeling and imagination.$j$,$j$A symbol represents a larger idea.$j$,$j$Mood is the feeling created by the writing.$j$,$j$Poe wrote tales and poems of mystery and dread.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: The Romantic Imagination$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 7, $j$Check 2.2: Hawthorne, Allegory and the Parable$j$, $j${"questions": [{"q": "An allegory is a story in which:", "options": ["Everything is literal only", "There are no characters", "The author lists facts", "Characters and events stand for deeper ideas"]}, {"q": "A parable is:", "options": ["A short story that teaches a spiritual lesson", "A type of math problem", "A map", "A list of rules"]}, {"q": "A universal theme is:", "options": ["The author's birthday", "A single character's name", "A rhyme scheme", "A message found across times and cultures"]}, {"q": "In the lantern allegory, the crack stands for:", "options": ["The road", "The wind", "A hidden fault in the heart", "The child's voice"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Hawthorne, Allegory and the Parable$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,3,2}'::int[], array[$j$An allegory has a surface story and a deeper meaning.$j$,$j$Parables teach spiritual lessons through simple stories.$j$,$j$Universal themes appear in many eras and places.$j$,$j$The crack is the hidden fault, not the outside pressure.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: Hawthorne, Allegory and the Parable$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 8, $j$Check 2.3: Emerson, Thoreau and Transcendentalism$j$, $j${"questions": [{"q": "Transcendentalism teaches that:", "options": ["Only wealth matters", "Individuals should think independently and nature reveals truth", "Everyone should follow the crowd", "Nature is worthless"]}, {"q": "Henry David Thoreau wrote about living near:", "options": ["Niagara Falls", "The Grand Canyon", "The Mississippi River", "Walden Pond"]}, {"q": "The thesis of an essay is:", "options": ["Its last word", "Its main claim", "Its title only", "Its page count"]}, {"q": "According to Proverbs 3:5, we should:", "options": ["Follow every opinion", "Trust only our own understanding", "Trust in the LORD with all our heart", "Avoid all wisdom"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Emerson, Thoreau and Transcendentalism$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,1,2}'::int[], array[$j$Transcendentalists valued self reliance and nature.$j$,$j$Thoreau wrote Walden about Walden Pond.$j$,$j$The thesis is the central claim.$j$,$j$Proverbs 3:5 says to trust in the LORD with all thine heart.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Emerson, Thoreau and Transcendentalism$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 9, $j$Check 2.4: Whitman, Dickinson and the Poetry of the Age$j$, $j${"questions": [{"q": "Free verse is poetry that:", "options": ["Has no words", "Always rhymes", "Does not follow regular rhyme or meter", "Is always about war"]}, {"q": "A metaphor says:", "options": ["One thing is like another using like or as", "One thing is another", "A lie", "Nothing"]}, {"q": "Personification is:", "options": ["Giving human traits to non human things", "Counting syllables", "Listing dates", "Using exact rhyme"]}, {"q": "Which poet is known for short, compressed poems and slant rhyme?", "options": ["Emily Dickinson", "Patrick Henry", "Mark Twain", "Walt Whitman"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Whitman, Dickinson and the Poetry of the Age$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,0,0}'::int[], array[$j$Free verse has no set rhyme or meter.$j$,$j$A metaphor says one thing is another.$j$,$j$Personification gives human traits to non human things.$j$,$j$Dickinson wrote short poems with slant rhyme.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: Whitman, Dickinson and the Poetry of the Age$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 10, $j$Unit Quiz 2: Romanticism and Transcendentalism$j$, $j${"questions": [{"q": "Romanticism emphasized:", "options": ["Only machines", "Imagination, emotion and nature", "Only law", "Only factual reports"]}, {"q": "An allegory has:", "options": ["A surface story and a deeper meaning", "Only dates", "No characters", "Only rhyme"]}, {"q": "A symbol is:", "options": ["A date", "Something that stands for a bigger idea", "A rhyme", "A kind of grammar"]}, {"q": "Transcendentalists valued:", "options": ["Self reliance and nature", "Following every rule of the crowd", "Ignoring nature", "Wealth above all"]}, {"q": "A simile compares using:", "options": ["Like or as", "Rhyme only", "Numbers", "Dates"]}, {"q": "Free verse is:", "options": ["A kind of prose", "A speech", "Poetry without regular rhyme or meter", "Poetry that always rhymes"]}, {"q": "Which describes a universal theme?", "options": ["A character's age", "A title", "A fact about one town", "A message found across eras and cultures"]}, {"q": "Parables like the sower in Matthew 13 teach by:", "options": ["Listing rules only", "Using ordinary scenes to point to spiritual truth", "Avoiding stories", "Giving only dates"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Romanticism and Transcendentalism$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,1,0,0,2,3,1}'::int[], array[$j$Romantic writers valued imagination and feeling.$j$,$j$Allegories work on two levels.$j$,$j$A symbol stands for a larger idea.$j$,$j$Emerson and Thoreau taught self reliance and love of nature.$j$,$j$A simile uses like or as.$j$,$j$Free verse has no fixed pattern.$j$,$j$Universal themes appear in many times and places.$j$,$j$Jesus used familiar scenes to teach heavenly truth.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Romanticism and Transcendentalism$j$ on conflict (item_id) do nothing;
